// SimCore executive demo (simulated model)
var jobs=['env','dyn','gnc'], t=0;
for(var s=0;s<3;s++){t+=0.01;console.log('t='+t.toFixed(2)+' '+jobs.join(','));}
console.log('SimCore: '+jobs.length+' jobs scheduled');

// SigDefine demo (simulated model)
var d={models:['grav','mass'],jobs:['grav','mass'],rate:50};
console.log('SigDefine: '+d.models.join(',')+' @ '+d.rate+'Hz');
console.log('generator wiring '+d.jobs.length+' jobs');

// Signature control demo (simulated model)
var err=8, u=0;
for(var i=0;i<5;i++){u=1.5*err;err*=0.55;console.log('u='+u.toFixed(2)+' err='+err.toFixed(2));}
console.log('Signature GNC converging');

// Signature Monte Carlo demo (simulated model)
var n=150, s=0, s2=0;
for(var i=0;i<n;i++){var v=50+((i*7919)%200)/10-10;s+=v;s2+=v*v;}
var m=s/n, sd=Math.sqrt(s2/n-m*m);
console.log(n+' runs mean='+m.toFixed(1)+' sd='+sd.toFixed(1));

// SigLink demo (simulated model)
var f=['veh','gnd','ops'];
for(var s=0;s<2;s++){console.log('t='+s+'s: '+f.join(',')+' synced');}
console.log('SigLink: '+f.length+' federates');

// SigView demo (simulated model)
var v={alt:90000,vel:7600};
for(var k in v){console.log('SigView: '+k+'='+v[k]);}
console.log('live display bound');

// Signature HIL demo (simulated model)
var f=4, dt=0.02, ok=0;
for(var i=0;i<f;i++){var w=0.016;if(w<=dt)ok++;console.log('frame '+i+' '+(w<=dt?'ok':'overrun'));}
console.log(ok+'/'+f+' frames on time');

// Case file demo (simulated model)
var cases=[['a',1],['b',2],['c',3]];
for(var i=0;i<cases.length;i++){console.log('case '+cases[i][0]+' cfg='+cases[i][1]);}
console.log(cases.length+' cases, one binary');

// Signature filter demo (simulated model)
var e=0, a=0.85, m=[5.1,4.8,5.0,5.2];
for(var i=0;i<m.length;i++){e=a*e+(1-a)*m[i];console.log('est='+e.toFixed(2));}
console.log('Signature filter fused');

// Signature EDL demo (simulated model)
var alt=100000;
for(var i=0;i<5;i++){alt=Math.max(0,alt-20000);console.log('alt='+(alt/1000)+'km');}
console.log('Signature EDL profile done');

// Signature fault demo (simulated model)
var ok=[1,1,1,1];ok[1]=0;
var n=ok.reduce(function(a,b){return a+b;},0);
console.log('actuators '+n+'/4 healthy -> FDIR reallocates');
console.log('Signature recovery engaged');

// Signature campaign demo (simulated model)
var r=[['S-GNC-1',150],['S-EDL-2',250]], t=0;
for(var i=0;i<r.length;i++){t+=r[i][1];console.log(r[i][0]+': '+r[i][1]);}
console.log('Signature campaign: '+t+' cases');

// Reference vehicle demo (simulated model)
var v=10500;
for(var i=0;i<3;i++){v-=2500;console.log('entry v='+v+' m/s');}
console.log('reference vehicle corridor held');

// SigView custom demo (simulated model)
var w=['dial','chart','3d'];
for(var i=0;i<w.length;i++){console.log('widget: '+w[i]+' bound');}
console.log(w.length+' live widgets');

// SimCore pipeline demo (simulated model)
var p=['models','SigDefine','generate','cases','batches','record','SigView','evidence'];
for(var i=0;i<p.length;i++){console.log((i+1)+'/'+p.length+' '+p[i]);}
console.log('Signature pipeline complete');
